        vm.startPrank(owner);
        cmove.addBlackList(victim);
        vm.stopPrank();

        // The oracle will verify blackListedList[victim] == true via storage check
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
